styles.css:
position: relative;
overflow: hidden;
isolation: isolate;
--ls-glass-card-background-rest: color-mix(in srgb, var(--wp--custom--color--surface--card) 24%, transparent);
--ls-glass-card-border-rest: color-mix(in srgb, var(--wp--custom--color--surface--highlight) 35%, transparent);
--ls-glass-card-top-highlight: color-mix(in srgb, var(--wp--custom--color--surface--highlight) 82%, transparent);
--ls-glass-card-side-highlight: color-mix(in srgb, var(--wp--custom--color--surface--highlight) 72%, transparent);
--ls-glass-card-side-tail: color-mix(in srgb, var(--wp--custom--color--surface--highlight) 30%, transparent);
--ls-glass-card-focus-width: 2px;
--ls-glass-card-focus-offset: 4px;
--ls-glass-card-background-hover: color-mix(in srgb, var(--wp--custom--color--surface--card) 34%, transparent);
--ls-glass-card-border-hover: color-mix(in srgb, var(--wp--custom--color--link--accent) 32%, var(--wp--custom--color--surface--highlight) 30%, transparent);
--ls-glass-card-shadow-hover: var(--wp--custom--shadow--elevation--300), var(--wp--custom--shadow--interactive--accent);
--ls-glass-card-focus-colour: var(--wp--custom--color--focus--ring);
--ls-glass-card-lift: var(--wp--custom--animation--lift--md);
background: var(--ls-glass-card-background-rest);
border-color: var(--ls-glass-card-border-rest);
box-shadow: var(--wp--custom--shadow--elevation--200);
outline: var(--ls-glass-card-focus-width) solid transparent;
outline-offset: var(--ls-glass-card-focus-offset);

& > * {
	position: relative;
	z-index: var(--wp--custom--z-index--content);
}

&::before {
	content: "";
	pointer-events: none;
	border-radius: inherit;
	z-index: var(--wp--custom--z-index--base);
	position: absolute;
	inset: auto 0 auto 0;
	top: 0;
	height: 1px;
	background: linear-gradient(90deg, transparent, var(--ls-glass-card-top-highlight), transparent);
}

&::after {
	content: "";
	pointer-events: none;
	border-radius: inherit;
	z-index: var(--wp--custom--z-index--base);
	position: absolute;
	inset: 0 auto 0 0;
	width: 1px;
	background: linear-gradient(180deg, var(--ls-glass-card-side-highlight), transparent, var(--ls-glass-card-side-tail));
}
